/*
 * Called by "npm version <new version>" (see the "version" script in package.json), after
 * npm has written the new number into package.json. It copies the number into the extension
 * manifest and the README badge and stops if CHANGELOG.md has no entry for it.
 * server/integrity.json is regenerated by the next step of the same npm script.
 */
"use strict";
const fs = require("fs");
const path = require("path");
const ROOT = path.resolve(__dirname, "..");
const file = f => path.join(ROOT, f);
const version = JSON.parse(fs.readFileSync(file("package.json"), "utf8")).version;

const changelog = fs.readFileSync(file("CHANGELOG.md"), "utf8");
if (!new RegExp("^## " + version.replace(/\./g, "\\.") + "\\b", "m").test(changelog)) {
  console.error(`CHANGELOG.md has no "## ${version}" entry. Write it first, then run npm version again.`);
  process.exit(1);
}

const manifestPath = file("extension/manifest.json");
const manifest = fs.readFileSync(manifestPath, "utf8");
const newManifest = manifest.replace(/("version":\s*")[\d.]+(")/, "$1" + version + "$2");
if (newManifest === manifest && JSON.parse(manifest).version !== version) throw new Error("could not set the version in extension/manifest.json");
fs.writeFileSync(manifestPath, newManifest);

const readmePath = file("README.md");
const readme = fs.readFileSync(readmePath, "utf8")
  .replace(/badge\/release-v[\d.]+-/, "badge/release-v" + version + "-")
  .replace(/alt="Release v[\d.]+"/, 'alt="Release v' + version + '"');
fs.writeFileSync(readmePath, readme);

console.log(`release ${version}: extension/manifest.json and README.md updated`);
